def _affine_relu(x, y):
    # Same four in-place steps as the verified eager implementation: one fresh
    # buffer, no redundant copy, no extra temporaries.
    out = x * 1.25
    out.add_(y, alpha=0.75)
    out.sub_(0.125)
    out.clamp_min_(0)
    return out


