_CAPTURE_DISABLED = False
_MAX_GRAPHS = 16
_SIDE_STREAM = None


def _warm_stream():
    global _SIDE_STREAM
    if _SIDE_STREAM is None:
        _SIDE_STREAM = torch.cuda.Stream()
    return _SIDE_STREAM


def _capture(x, y):
    graph = torch.cuda.CUDAGraph()
    side = _warm_stream()
    side.wait_stream(torch.cuda.current_stream())
