    # Kernels recorded during capture are not executed, so produce the value once.
    graph.replay()
    return graph, static_out


def _key_for(x, y):
    return (
        x.data_ptr(), y.data_ptr(),
        x.device.index, y.device.index,
        tuple(x.shape), tuple(x.stride()),
        tuple(y.shape), tuple(y.stride()),
    )


