Baseline contract preserved verbatim: inputs_for / get_inputs / get_test_cases /
get_benchmark_inputs / reference are unchanged, and run(inputs) produces exactly
the same numerics as the baseline chain.

Round-4 optimization (distinct from the previous in-place-chain candidate):
at 32x256 the kernel work is trivial and the cost is almost entirely per-op
launch + Python dispatch (4 launches per call).  For an input signature that
repeats (same buffers, shape, stride, dtype, device) the four elementwise
kernels are recorded once into a CUDA graph and afterwards re-issued with a
single graph launch, removing 3 of 4 launches and most of the dispatch cost.
The graph reads the caller's live input buffers, so a replay always reflects
the current input contents; the static graph output is cloned before being
returned so callers never receive an aliased/reused buffer.  Any capture
failure (unsupported driver/context, capture conflict, exhausted budget) falls
back permanently to the plain eager chain, which is the previously
correctness-verified implementation.
"""

import torch


def inputs_for(rows, cols):
    x = (torch.linspace(-2, 2, rows * cols, device='cuda', dtype=torch.float32) + 3).reshape(rows, cols)
    return {'x': x, 'y': x.flip(-1)}


def get_inputs():
    return inputs_for(32, 256)


def get_test_cases():
    return [
        {'name': 'minimal', 'category': 'minimal', 'inputs': inputs_for(1, 1)},
        {'name': 'representative', 'category': 'representative', 'inputs': get_inputs()},
        {'name': 'boundary', 'category': 'boundary', 'inputs': inputs_for(2, 32)},
        {'name': 'ragged', 'category': 'ragged', 'inputs': inputs_for(3, 17)},
    ]


def get_benchmark_inputs():
    return [{'name': 'primary', 'inputs': get_inputs()}, {'name': 'small', 'inputs': inputs_for(2, 32)}]


def reference(inputs):
    return torch.relu(inputs['x'] * 1.25 + inputs['y'] * 0.75 - 0.125)


# --- implementation under test -------------------------------------------------

def _affine_relu(x, y):
    # Same four in-place steps as the verified eager implementation: one fresh
    # buffer, no redundant copy, no extra temporaries.
    out = x * 1.25
    out.add_(y, alpha=0.75)
    out.sub_(0.125)
    out.clamp_min_(0)
    return out


_GRAPHS = {}
_CAPTURE_DISABLED = False
_MAX_GRAPHS = 16
_SIDE_STREAM = None


def _warm_stream():
    global _SIDE_STREAM
    if _SIDE_STREAM is None:
        _SIDE_STREAM = torch.cuda.Stream()
    return _SIDE_STREAM


def _capture(x, y):
    graph = torch.cuda.CUDAGraph()
    side = _warm_stream()
    side.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(side):
        # Warm up the lazy init paths (allocator, kernels) off the capture stream.
        for _ in range(3):
            _affine_relu(x, y)
    torch.cuda.current_stream().wait_stream(side)
    with torch.cuda.graph(graph):
        static_out = _affine_relu(x, y)
    # Kernels recorded during capture are not executed, so produce the value once.
    graph.replay()
    return graph, static_out


def _key_for(x, y):
    return (
        x.data_ptr(), y.data_ptr(),
        x.device.index, y.device.index,
        tuple(x.shape), tuple(x.stride()),
        tuple(y.shape), tuple(y.stride()),
    )


def run(inputs):
    global _CAPTURE_DISABLED
    x = inputs['x']
    y = inputs['y']

    if _CAPTURE_DISABLED or not x.is_cuda or not y.is_cuda:
        return _affine_relu(x, y)
    if x.dtype != torch.float32 or y.dtype != torch.float32:
        return _affine_relu(x, y)

    try:
        key = _key_for(x, y)
    except Exception:
        return _affine_relu(x, y)

    entry = _GRAPHS.get(key)
    if entry is None:
        if len(_GRAPHS) >= _MAX_GRAPHS:
            return _affine_relu(x, y)
        try:
            entry = _capture(x, y)
        except Exception:
            # Unsupported / conflicting capture context: never retry, keep eager.
            _CAPTURE_DISABLED = True
            _GRAPHS.clear()
            return _affine_relu(x, y)
        _GRAPHS[key] = entry

    graph, static_out = entry
    graph.replay()
    return static_out.clone()
