# --- cached, read-only helpers for the implementation path -------------------
# The affine constants are hoisted out of run(inputs) so that no scalar/bias
# tensor is materialised per call (device->host sync free, launch free). The
# cache only ever stores tensors that run(inputs) treats as read-only, so it is
# safe to share them across calls and across the four correctness shapes.
_bias_cache = {}
_scalar_cache = {}

def _bias_like(x):
    key = (x.shape, x.device, x.dtype)
    bias = _bias_cache.get(key)
    if bias is None:
        bias = x.new_full(x.shape, -0.125)
        _bias_cache[key] = bias
    return bias

def _scalar(value, like):
    key = (value, like.device, like.dtype)
    scalar = _scalar_cache.get(key)
    if scalar is None:
        scalar = like.new_tensor(value)
        _scalar_cache[key] = scalar
    return scalar

def run(inputs):
    # Same math as reference(): relu(1.25 * x + 0.75 * y - 0.125).
    # Fused into 3 elementwise kernels operating on one freshly allocated
    # output buffer, instead of 6 kernels (4 temporaries + relu + clone):
    #   1. out  = -0.125 + 1.25 * x        (addcmul, single allocation)
    #   2. out += 0.75 * y                 (in-place addcmul_)
    #   3. out  = max(out, 0)              (in-place clamp_min_)
    x = inputs['x']
    y = inputs['y']
    out = torch.addcmul(_bias_like(x), x, _scalar(1.25, x), 1.0)
    out.addcmul_(y, _scalar(0.75, x), 1.0)
    out.clamp_min_(0)
    return out
